import{_ as t}from"./chunks/ConsoleLauncher_Config.943Wsr3w.js";import{_ as a,o as n,c as o,ag as i}from"./chunks/framework.D9ghT4bC.js";const g=JSON.parse('{"title":"Simulations","description":"","frontmatter":{},"headers":[],"relativePath":"Other/Simulations.md","filePath":"Other/Simulations.md"}'),s={name:"Other/Simulations.md"};function r(h,e,u,l,d,c){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="simulations" tabindex="-1">Simulations <a class="header-anchor" href="#simulations" aria-label="Permalink to &quot;Simulations&quot;">​</a></h1><p>The codebase supports the ability to run automated simulations and compare the results for AI development.</p><h2 id="enabling" tabindex="-1">Enabling <a class="header-anchor" href="#enabling" aria-label="Permalink to &quot;Enabling&quot;">​</a></h2><p>Set up a custom build configuration.</p><p>Set the working directory to android/assets, just like when running desktop. And use the <code>unciv.desktop.main</code> module. <img src="'+t+'" alt="image"></p><h2 id="running-sims" tabindex="-1">Running Sims <a class="header-anchor" href="#running-sims" aria-label="Permalink to &quot;Running Sims&quot;">​</a></h2><p>Execute the ConsoleLauncher Build Configuration set up above. Results should appear in the Console of the IDE.</p><h2 id="configuring-sims" tabindex="-1">Configuring Sims <a class="header-anchor" href="#configuring-sims" aria-label="Permalink to &quot;Configuring Sims&quot;">​</a></h2><p>Within the <code>desktop\\src\\ConsoleLauncher.kt</code> file, you can adjust the number of sims to run, which nations to use, etc.</p><p>Recommend using generic civs with no Uniques. You can see the code add a generic <code>Nation</code> to the <code>ruleset</code> object, and you can key different behavior throughout the code using the Nation Name constant as the control switch.</p><p>You can also adjust the game parameters and map parameters. To get more consistent results, turning off Natural Wonders and Barbarians can help.</p><p>By default the order of players is randomized to make it more fair.</p><p>The <code>statTurns</code> list parameter allows the system to save certain stats at particular turns so you can track it over the course of the games.</p><h2 id="understanding-results" tabindex="-1">Understanding Results <a class="header-anchor" href="#understanding-results" aria-label="Permalink to &quot;Understanding Results&quot;">​</a></h2><p>By default the console will report the number of wins per civ, type of win, and the <code>popsum</code> at the end of the game. This is the average amount of population for the whole civ at the end of the game.</p><p>It is a good habit to validate your expectations for which Civ would win, how they would win, and any changes in the reported values. Some changes won&#39;t show up in the win rates, so are better tested by making a scenario in the Map Editor or with the in-game Console then testing the AI behaviors.</p><p>The p-value is also reported, showing based on the winrate how likely this result is in a binomial test. If this value is very small, then there is a low chance this arose out of random chance and that your changes made a statistically significant change in the overall winrate. Running 200-400 Sims is usually a good baseline point.</p>',17)])])}const f=a(s,[["render",r]]);export{g as __pageData,f as default};
